import{_ as t,o as l,c as o,a3 as i}from"./chunks/framework.C6R8kWFE.js";const c=JSON.parse('{"title":"功能清单","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1791053025000}'),n={name:"features.md"};function s(g,r,a,e,h,d){return l(),o("div",null,[...r[0]||(r[0]=[i('<h1 id="功能清单" tabindex="-1">功能清单 <a class="header-anchor" href="#功能清单" aria-label="Permalink to &quot;功能清单&quot;">​</a></h1><p>以下按实际页面与业务能力介绍内置功能；AI、在线聊天、代码生成、工作流和打印属于可选模块。</p><p><a href="./preview">查看完整功能截图</a></p><h2 id="工作台与身份权限" tabindex="-1">工作台与身份权限 <a class="header-anchor" href="#工作台与身份权限" aria-label="Permalink to &quot;工作台与身份权限&quot;">​</a></h2><ul><li><strong>工作台</strong>：通过可定制小组件展示统计、图表、公告和待办，支持调整布局与保存个人看板。</li><li><strong>控制中心</strong>：集中展示可进入的租户与平台管理入口，支持切换租户和选择工作上下文。</li><li><strong>登录认证</strong>：支持账号密码、手机和邮箱验证码、第三方登录及双因素验证，提供验证码、登录节流和账号锁定防护。</li><li><strong>个人中心</strong>：维护个人资料、密码、手机和邮箱，管理第三方绑定、登录设备、通知偏好、租户归属和个人使用统计。</li><li><strong>用户管理</strong>：查询与维护用户，支持高级搜索、启用禁用、多角色与多部门配置、直接授权、数据范围、账号锁定、密码重置、模拟登录和强制下线。</li><li><strong>在线用户</strong>：查看活跃会话、客户端和实时连接状态，支持按用户检索并吊销指定会话。</li><li><strong>角色管理</strong>：维护角色、继承关系和成员，批量添加或移除成员，配置菜单权限、操作权限和数据范围。</li><li><strong>组织机构</strong>：以树形列表管理部门层级，查看子部门和成员，维护部门负责人及成员岗位、工号、职级和入职信息。</li><li><strong>岗位管理</strong>：维护岗位名称、编码、排序和启停状态，查看岗位详情并供部门成员配置使用。</li><li><strong>权限管理</strong>：集中维护模块、资源和操作权限，配置权限编码、接口路径、请求方法、平台或租户作用域及审计要求。</li><li><strong>菜单管理</strong>：以树形结构维护目录、菜单与按钮，配置组件路径、图标、排序、可见性、缓存、外链和关联权限。</li><li><strong>字段安全</strong>：按实体字段与授权对象配置字段读取、写入和脱敏策略，控制敏感字段的展示与修改。</li><li><strong>授权申请与委托</strong>：处理权限申请的批准、拒绝和撤回，支持限时委托角色或权限并随时撤销。</li><li><strong>审批中心</strong>：查询审批事项、审批状态和处理记录，支持查看详情、批准、拒绝及撤回。</li><li><strong>审批约束</strong>：维护职责分离、互斥、基数和条件约束，配置适用对象、规则参数及违规处理方式。</li></ul><h2 id="租户与消息协作" tabindex="-1">租户与消息协作 <a class="header-anchor" href="#租户与消息协作" aria-label="Permalink to &quot;租户与消息协作&quot;">​</a></h2><ul><li><strong>租户管理</strong>：维护租户状态、版本、到期与配额，分步初始化租户数据库和管理员，管理成员、运维支持成员及所有权转移。</li><li><strong>版本套餐</strong>：配置套餐价格、计费周期、用户与存储配额以及权限白名单，控制租户可用功能。</li><li><strong>我的订阅</strong>：查看当前租户的版本、订阅期限和用户、存储用量，了解配额与可用权益。</li><li><strong>通知公告</strong>：维护并发布通知，按用户、角色或部门定向投递，配置展示与强制阅读方式，查看阅读统计和未读人员。</li><li><strong>我的消息</strong>：查看站内通知详情，筛选待处理消息，支持单条或全部标为已读及确认阅读。</li><li><strong>消息模板</strong>：集中维护邮件、短信、站内通知和机器人模板，使用模板变量组织内容并支持租户覆盖。</li><li><strong>邮件短信</strong>：查询邮件和短信发送记录、接收对象及发送结果，查看内容详情并重发失败消息。</li><li><strong>在线聊天</strong>：支持单聊、群聊、部门会话与 AI 助手会话，通过实时推送展示消息、未读状态及会话信息。</li><li><strong>聊天审计</strong>：按会话与消息条件检索聊天记录，查看会话成员和消息详情，支持内容合规审查。</li></ul><h2 id="文件与系统管理" tabindex="-1">文件与系统管理 <a class="header-anchor" href="#文件与系统管理" aria-label="Permalink to &quot;文件与系统管理&quot;">​</a></h2><ul><li><strong>文件管理</strong>：查询、上传、下载和预览文件，维护元数据、归档与恢复状态，查看存储副本并管理主存储。</li><li><strong>存储配置</strong>：配置本地、S3、OSS、COS 和 MinIO 等存储通道，支持启用禁用及默认存储设置。</li><li><strong>导出中心</strong>：统一查看异步导出任务的状态与结果，支持 CSV、XLSX 文件下载、取消待执行任务和删除记录。</li><li><strong>字典管理</strong>：联动维护字典分类与字典项，配置编码、值、默认项、排序和状态，为搜索与表单提供统一选项。</li><li><strong>参数配置</strong>：维护平台与租户参数，按分组和状态查询配置，查看配置详情并管理参数值。</li><li><strong>业务编号</strong>：配置编号前缀、日期、流水位数、重置周期和时区，预览格式，执行安全重置并查看永久发号记录。</li><li><strong>任务调度</strong>：维护定时与间隔任务，支持 Cron 可视化配置、启用暂停、立即执行、重试策略及运行日志详情查看。</li><li><strong>缓存管理</strong>：按键或匹配模式查询缓存，以树形分组查看键和内容，支持编辑缓存值、按键或批量清理。</li><li><strong>服务监控</strong>：展示 CPU、内存、磁盘、网络、GPU、主板和运行时信息，辅助查看服务资源与运行状态。</li><li><strong>版本管理</strong>：查看当前系统版本、版本说明与数据库迁移信息，集中核对升级状态。</li><li><strong>邮件配置</strong>：维护邮件发送通道与服务器参数，管理启用状态及默认邮件配置。</li><li><strong>短信配置</strong>：维护短信服务商与发送配置，管理启用状态及默认短信通道。</li><li><strong>机器人配置</strong>：管理钉钉、飞书和企业微信 Webhook 机器人通道，配置状态及默认通知机器人。</li><li><strong>Telegram 机器人</strong>：维护多个 Telegram Bot 实例的连接配置、启用状态和相关说明。</li><li><strong>应用管理</strong>：注册与维护 OAuth2 / OIDC 应用，配置客户端类型、授权方式和回调地址，管理应用状态及密钥。</li><li><strong>开放接口凭证</strong>：在个人中心自助管理 OpenAPI 调用凭证，申请、查看和轮换签名调用所需的密钥。</li></ul><h2 id="日志与审计" tabindex="-1">日志与审计 <a class="header-anchor" href="#日志与审计" aria-label="Permalink to &quot;日志与审计&quot;">​</a></h2><ul><li><strong>访问日志</strong>：查询请求路径、请求方法、状态码、耗时和客户端信息，查看详情并跳转关联链路。</li><li><strong>开放接口日志</strong>：查询开放接口调用与签名鉴权结果，查看请求响应详情及关联链路。</li><li><strong>操作日志</strong>：记录业务操作、执行结果和耗时，查看操作描述、客户端信息及关联链路。</li><li><strong>登录日志</strong>：查询登录成功、失败、退出及模拟登录等事件，查看客户端、IP 与登录详情。</li><li><strong>异常日志</strong>：检索异常类型、错误信息与发生位置，查看堆栈和关联请求以定位问题。</li><li><strong>数据变更日志</strong>：记录实体新增、修改、删除与恢复，展示字段变更前后差异并关联操作链路。</li><li><strong>权限变更日志</strong>：记录角色、用户和权限授权变更，查询操作对象、变更内容与关联链路。</li><li><strong>日志链路追踪</strong>：按 TraceId、用户、会话或 IP 聚合多类日志，以时间线串联操作，并用流向图与时间分布分析定位异常。</li><li><strong>升级记录</strong>：查询数据库升级脚本执行台账，查看版本、执行状态、耗时与错误详情。</li></ul><h2 id="开发与扩展模块" tabindex="-1">开发与扩展模块 <a class="header-anchor" href="#开发与扩展模块" aria-label="Permalink to &quot;开发与扩展模块&quot;">​</a></h2><ul><li><strong>代码生成</strong>：管理数据源、表结构、字段和模板，支持单表、树形、主从全栈生成、代码预览、下载与生成历史查看。</li><li><strong>AI 提供商</strong>：配置模型服务商、连接地址和模型，安全托管密钥，测试连接并设置默认提供商。</li><li><strong>AI 提示词</strong>：集中维护提示词编码、内容和状态，为 AI 对话及业务场景复用提示词模板。</li><li><strong>知识库</strong>：导入知识文档并建立向量索引，支持重建索引、检索问答和来源引用，按租户隔离知识数据。</li><li><strong>AI 助手</strong>：配置助手身份、模型与提示词，设置默认助手并接入在线聊天会话。</li><li><strong>流程定义</strong>：可视化设计流程节点与连线，维护草稿、发布、停用和归档状态，支持版本管理及启动流程。</li><li><strong>流程实例</strong>：查看流程运行状态、节点与详情，支持挂起、恢复、取消、终止、故障重试及发送流程信号。</li><li><strong>我的待办</strong>：集中处理人工流程任务，支持批准、拒绝、转办和加签，跟踪任务办理状态。</li><li><strong>打印模板</strong>：拖拽设计文本、表格、图片和条码，配置纸张、数据源与样例数据，支持缩放排版、JSON 查看、预览和打印。</li></ul><h2 id="通用使用体验" tabindex="-1">通用使用体验 <a class="header-anchor" href="#通用使用体验" aria-label="Permalink to &quot;通用使用体验&quot;">​</a></h2><ul><li><strong>偏好设置</strong>：配置亮暗主题、主题色、布局、紧凑度、水印与交互偏好，支持个人偏好云端同步。</li><li><strong>高级列表</strong>：统一提供组合搜索、个人视图、列设置、多列排序、密度切换、树形展示、速览与导出能力。</li><li><strong>内容编辑</strong>：提供富文本、Markdown、代码与 JSON 编辑查看，以及 Cron 表达式可视化配置。</li><li><strong>全局导航</strong>：提供多标签页、收藏夹、全局搜索、通知与任务反馈，支持多语言、时区切换和锁屏。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./backend/permission">权限模型</a>：权限与数据范围</li><li><a href="./backend/introduction">系统架构</a>：模块划分与数据流</li><li><a href="./getting-started">快速开始</a>：本地运行</li></ul>',17)])])}const f=t(n,[["render",s]]);export{c as __pageData,f as default};
